void export(ExportRequest request, HttpServletResponse response) throws IOException {
    authorization.requireExport(request.tenant(), request.scope());
    response.setBufferSize(8192);
    response.setCharacterEncoding("UTF-8");
    response.setContentType("text/csv");
    response.setHeader("Content-Disposition", "attachment; filename=orders.csv");
    try (Rows rows = queries.openCursor(request)) {
        PrintWriter writer = response.getWriter();
        writer.write("id,status\r\n");
        if (settings.flushHeader()) response.flushBuffer();
        long count = 0;
        while (rows.hasNext()) {
            csv.write(rows.next(), writer);
            count++;
        }
        writer.write("#COMPLETE," + count + "\r\n");
        writer.flush();
        if (writer.checkError()) throw new ExportWriteFailure();
    } catch (ExportReadFailure failure) {
        errorRenderer.render(response);
    }
}

